    An island is a group of adjacent cells with value 1, connected 4-directionally.
    Handles empty grid and non‑rectangular inputs defensively.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows and isinstance(grid[0], (list, tuple)) else 0
    # Guard against irregular rows; treat missing cells as 0.
    visited = [[False] * cols for _ in range(rows)]

    def bfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows or j < 0 or j >= cols:
                continue
            if visited[i][j] or grid[i][j] != 1:
                continue
            visited[i][j] = True
            stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])

    count = 0
    for i in range(rows):
        # If rows have varying lengths, skip out‑of‑range columns safely.
        for j in range(cols):
            if not visited[i][j] and grid[i][j] == 1:
                bfs(i, j)
                count += 1
    return count

