def solve(grid):
    """Count the number of islands in a binary grid (list of lists or jagged rows).
    Islands are groups of adjacent cells with value 1, connected 4-directionally.
    Handles empty grid and rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    # Determine column count for each row separately (jagged support)
    visited = [set() for _ in range(rows)]

    def bfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if (i, j) in visited[i]:
                continue
            if grid[i][j] != 1:
                continue
            visited[i].add((i, j))
            # Explore neighbors
            stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])

    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if (i, j) not in visited[i] and grid[i][j] == 1:
                bfs(i, j)
                count += 1
    return count

