def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting (tails) with binary search.
    """
    import bisect
    tails = []
    for x in nums:
        # find insertion point for x in tails (first >= x)
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

